/// same RFC 7523 client authentication against any token endpoint that registered the
/// custodian's public key. `s3-static-presign`: an access-key pair for an
/// S3-compatible store that cannot federate; the custodian presigns per-object URLs
/// and never releases the key. `sui-signer`: a Sui address derived from the
/// custodian's key; the custodian signs only allow-listed transactions.
/// `static-secret`: an API key or token used inside the custodian by a named driver;
/// last resort, never released. Plain OpenID Connect discovery federation is
/// deliberately absent. It works by the provider fetching the issuer's JWKS from a
/// public URL, which either makes the custodian reachable from the internet or makes
/// whoever hosts a copy of the JWKS able to mint credentials for every federated role.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const AuthModel(String value) {
  static const AuthModel awsRolesAnywhere = AuthModel('aws-roles-anywhere');
  static const AuthModel gcpWifPinned = AuthModel('gcp-wif-pinned');
  static const AuthModel azureCert = AuthModel('azure-cert');
  static const AuthModel oauth2PrivateKeyJwt =
      AuthModel('oauth2-private-key-jwt');
  static const AuthModel s3StaticPresign = AuthModel('s3-static-presign');
  static const AuthModel suiSigner = AuthModel('sui-signer');
  static const AuthModel staticSecret = AuthModel('static-secret');

  /// Every value this specification's schema permits.
  static const List<AuthModel> values = <AuthModel>[
    awsRolesAnywhere,
    gcpWifPinned,
    azureCert,
    oauth2PrivateKeyJwt,
    s3StaticPresign,
    suiSigner,
    staticSecret
  ];
}

